<style>
#boschino-model-picker .inventory-status-with-tooltip,
#boschino-fallback-grid .inventory-status-with-tooltip {
  position: relative;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  cursor: help;
}

#boschino-model-picker .inventory-tooltip,
#boschino-fallback-grid .inventory-tooltip {
  position: absolute;
  left: 0;
  bottom: calc(100% + 10px);
  z-index: 30;
  min-width: 220px;
  max-width: 280px;
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(28, 28, 28, 0.96);
  color: #fff;
  font-size: 12px;
  line-height: 1.45;
  font-weight: 500;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.22);
  opacity: 0;
  visibility: hidden;
  transform: translateY(6px);
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s ease;
  pointer-events: none;
}

#boschino-model-picker .inventory-tooltip::after,
#boschino-fallback-grid .inventory-tooltip::after {
  content: "";
  position: absolute;
  left: 18px;
  top: 100%;
  border-width: 6px;
  border-style: solid;
  border-color: rgba(28, 28, 28, 0.96) transparent transparent transparent;
}

#boschino-model-picker .inventory-status-with-tooltip:hover .inventory-tooltip,
#boschino-model-picker .inventory-status-with-tooltip:focus .inventory-tooltip,
#boschino-model-picker .inventory-status-with-tooltip:focus-within .inventory-tooltip,
#boschino-fallback-grid .inventory-status-with-tooltip:hover .inventory-tooltip,
#boschino-fallback-grid .inventory-status-with-tooltip:focus .inventory-tooltip,
#boschino-fallback-grid .inventory-status-with-tooltip:focus-within .inventory-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

/* Klikatelnější tlačítka spotřebičů + šipka */
#boschino-model-picker .boschino-appliance-list {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  overflow-x: visible;
  padding-bottom: 0;
}

#boschino-model-picker .boschino-appliance-trigger {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 1 auto;
  white-space: nowrap;
  padding: 8px 10px;
  min-height: auto;
  font-size: 13px;
  line-height: 1.1;
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease;
  box-shadow: none;
}

#boschino-model-picker .boschino-appliance-trigger::after {
  content: "›";
  font-size: 13px;
  line-height: 1;
  color: rgba(42, 56, 133, 0.52);
  transition: transform 0.16s ease, color 0.16s ease;
}

@media screen and (max-width: 989px) {
  #boschino-model-picker .boschino-appliance-list {
    overflow-x: auto;
    padding-bottom: 4px;
  }

  #boschino-model-picker .boschino-appliance-trigger {
    flex: 0 0 auto;
  }
}

#boschino-model-picker .boschino-appliance-trigger:hover,
#boschino-model-picker .boschino-appliance-trigger:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(42, 56, 133, 0.18);
}

#boschino-model-picker .boschino-appliance-trigger:hover::after,
#boschino-model-picker .boschino-appliance-trigger:focus-visible::after,
#boschino-model-picker .boschino-appliance-trigger.active::after {
  transform: translateX(2px);
  color: #2a3885;
}

#boschino-model-picker .boschino-appliance-trigger:focus-visible {
  outline: none;
}

/* Šipka u fallback toggle */
#boschino-model-picker .boschino-fallback {
  margin-top: 22px;
  border: 1px solid rgba(42, 56, 133, 0.12);
  border-left: 5px solid #69c7d0;
  border-radius: 12px;
  background: #fff;
  overflow: hidden;
}

#boschino-model-picker .boschino-fallback-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  cursor: pointer;
  background: transparent;
  border: 0;
  text-align: left;
  padding: 16px 18px;
}

#boschino-model-picker .boschino-fallback-toggle::after {
  content: "";
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  border-right: 2px solid rgba(0, 0, 0, 0.65);
  border-bottom: 2px solid rgba(0, 0, 0, 0.65);
  transform: rotate(45deg);
  transition: transform 0.18s ease;
  margin-right: 2px;
}

#boschino-model-picker .boschino-fallback.active .boschino-fallback-toggle::after {
  transform: rotate(225deg);
}

#boschino-model-picker .boschino-fallback-content {
  padding: 0 18px 18px;
}

/* Text výrobců až dole */
#boschino-model-picker .boschino-brand-note {
