<script>
document.addEventListener('DOMContentLoaded', function () {
  (async () => {
    const SUPABASE_URL = "https://hbntpqlpcrodrhfjxhpv.supabase.co/rest/v1";
    const RPC_URL = SUPABASE_URL + "/rpc/search_models";
    const SUPABASE_KEY = "sb_publishable_py5U4zoYoBusjy_rngRuWg_IcZ6o-AV";

    const SUPABASE_HEADERS = {
      "apikey": SUPABASE_KEY,
      "Authorization": "Bearer " + SUPABASE_KEY,
      "Content-Type": "application/json"
    };

    const TYPO_RULES = [
      { from: "0", to: "O" },
      { from: "O", to: "0" },
      { from: "1", to: "I" },
      { from: "I", to: "1" },
      { from: "8", to: "B" },
      { from: "B", to: "8" },
      { from: "5", to: "S" },
      { from: "S", to: "5" },
      { from: "2", to: "Z" },
      { from: "Z", to: "2" },
      { from: "VV", to: "W" },
      { from: "W", to: "VV" }
    ];

    const params = new URLSearchParams(window.location.search);
    const base = (params.get("base") || "").trim().toUpperCase();

    const statusEl = document.getElementById("boschino-model-picker-status");
    const listEl = document.getElementById("boschino-model-picker-list");

    function applianceSlug(value) {
      return String(value || "")
        .toLowerCase()
        .replace(/\s+/g, "")
        .replace(/\//g, "-")
        .replace(/\(/g, "_")
        .replace(/\)/g, "");
    }

    function applianceUrl(itemOrModel) {
      if (!itemOrModel) return null;

      if (typeof itemOrModel === "string") {
        return "/pages/appliance/" + applianceSlug(itemOrModel);
      }

      if (itemOrModel.shopify_handle) {
        return "/pages/appliance/" + itemOrModel.shopify_handle;
      }

      return "/pages/appliance/" + applianceSlug(itemOrModel.model_norm || "");
    }

    function escapeHtml(str) {
      return String(str || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    }

    function unique(values) {
      return [...new Set((values || []).filter(Boolean))];
    }

    function uniqueByModel(items) {
      return (items || []).filter(
        (item, index, arr) =>
          arr.findIndex(x => String(x.model_norm || "").trim() === String(item.model_norm || "").trim()) === index
      );
    }

    function isDigitsOnly(value) {
      return /^\d+$/.test(String(value || "").trim());
    }

    function isPartNumberCandidate(value) {
      return /^(?:00|1|2)\d{6}$/.test(String(value || "").trim());
    }

    function isWildcardCandidate(value) {
      const normalized = String(value || "").trim().toUpperCase();

      if (!normalized) return false;
      if (normalized.includes(" ")) return false;
      if (/[\/()]/.test(normalized)) return false;
      if (isPartNumberCandidate(normalized)) return false;
      if (isDigitsOnly(normalized)) return false;
      if (!normalized.includes("?")) return false;

      const knownChars = normalized.replace(/\?/g, "");
      return knownChars.length >= 2;
    }

    function applyRuleAt(value, index, from, to) {
      return value.slice(0, index) + to + value.slice(index + from.length);
    }

    function buildTypoVariantsOnce(value) {
      const variants = [];

      for (const rule of TYPO_RULES) {
        let startIndex = 0;

        while (startIndex < value.length) {
          const index = value.indexOf(rule.from, startIndex);
          if (index === -1) break;

          variants.push(applyRuleAt(value, index, rule.from, rule.to));
          startIndex = index + 1;
        }
      }

      return unique(variants).filter(v => v !== value);
    }

    function buildTypoVariantsTwice(value) {
      const once = buildTypoVariantsOnce(value);
      const twice = [];

      for (const firstVariant of once) {
        twice.push(...buildTypoVariantsOnce(firstVariant));
        if (twice.length > 200) break;
      }

      return unique(twice).filter(v => v !== value);
    }

    async function fetchExactAppliance(modelValue) {
      const url =
        SUPABASE_URL +
        "/appliances" +
        "?select=model_norm,shopify_handle" +
        "&model_norm=eq." + encodeURIComponent(modelValue) +
        "&limit=1";

      const res = await fetch(url, { headers: SUPABASE_HEADERS });
      if (!res.ok) return null;

      const data = await res.json();

      if (Array.isArray(data) && data.length > 0) {
        return {
          model_norm: (data[0].model_norm || "").trim(),
          shopify_handle: (data[0].shopify_handle || "").trim()
        };
      }

      return null;
    }

    async function fetchModelsRpc(q) {
      const res = await fetch(RPC_URL, {
        method: "POST",
        headers: SUPABASE_HEADERS,
        body: JSON.stringify({ q: (q || "").toUpperCase() })
      });

      if (!res.ok) return [];
      const data = await res.json();

      if (!Array.isArray(data)) return [];

      return data
        .map(item => {
          if (typeof item === "string") return item.trim();
          if (item && typeof item.model === "string") return item.model.trim();
          return "";
        })
        .filter(Boolean);
    }

    async function fetchAppliancesByModels(models) {
      const uniqueModels = unique(models.map(v => String(v || "").trim().toUpperCase())).slice(0, 50);
      if (!uniqueModels.length) return [];

      const conditions = uniqueModels
        .map(model => "model_norm.eq." + encodeURIComponent(model))
        .join(",");

      const url =
        SUPABASE_URL +
        "/appliances" +
        "?select=model_norm,shopify_handle" +
        "&or=(" + conditions + ")" +
        "&order=model_norm.asc" +
        "&limit=50";

      const res = await fetch(url, { headers: SUPABASE_HEADERS });
      if (!res.ok) return [];

      const data = await res.json();
      if (!Array.isArray(data)) return [];

      return data
        .map(item => ({
          model_norm: (item.model_norm || "").trim(),
          shopify_handle: (item.shopify_handle || "").trim()
        }))
        .filter(item => item.model_norm);
    }

    async function fetchPrefixCandidates(prefixValue) {
      const normalized = String(prefixValue || "").trim().toUpperCase();
      if (!normalized) return [];

      const url =
        SUPABASE_URL +
        "/appliances" +
        "?select=model_norm,shopify_handle" +
        "&model_norm=like." + encodeURIComponent(normalized + "%") +
        "&order=model_norm.asc" +
        "&limit=50";

      const res = await fetch(url, { headers: SUPABASE_HEADERS });
      if (!res.ok) return [];

      const data = await res.json();
      if (!Array.isArray(data)) return [];

      return data
        .map(item => ({
          model_norm: (item.model_norm || "").trim(),
          shopify_handle: (item.shopify_handle || "").trim()
        }))
        .filter(item => item.model_norm);
    }

    async function fetchWildcardCandidates(rawValue) {
      const normalized = String(rawValue || "").trim().toUpperCase();
      if (!isWildcardCandidate(normalized)) return [];

      const pattern = normalized.replace(/\?/g, "_");

      const url =
        SUPABASE_URL +
        "/appliances" +
        "?select=model_norm,shopify_handle" +
        "&model_norm=like." + encodeURIComponent(pattern) +
        "&order=model_norm.asc" +
        "&limit=50";

      const res = await fetch(url, { headers: SUPABASE_HEADERS });
      if (!res.ok) return [];

      const data = await res.json();
      if (!Array.isArray(data)) return [];

      return data
        .map(item => ({
          model_norm: (item.model_norm || "").trim(),
          shopify_handle: (item.shopify_handle || "").trim()
        }))
        .filter(item => item.model_norm);
    }

    async function fetchPossibleModelCandidates(rawValue) {
      const q = String(rawValue || "").trim().toUpperCase();
      if (!q) return [];

      if (isWildcardCandidate(q)) {
        return uniqueByModel(await fetchWildcardCandidates(q));
      }

      const exactMatch = await fetchExactAppliance(q);
      if (exactMatch) return [exactMatch];

      const rpcMatches = await fetchModelsRpc(q);
      if (rpcMatches.length) {
        const rpcAppliances = await fetchAppliancesByModels(rpcMatches);
        if (rpcAppliances.length) return uniqueByModel(rpcAppliances);
      }

      const prefixMatches = await fetchPrefixCandidates(q);
      if (prefixMatches.length) return uniqueByModel(prefixMatches);

      const canUseTypoLogic =
        !q.includes(" ") &&
        !q.includes("?") &&
        !isPartNumberCandidate(q) &&
        !isDigitsOnly(q);

      if (!canUseTypoLogic) return [];

      const singleVariants = buildTypoVariantsOnce(q);

      for (const variant of singleVariants) {
        const exactVariant = await fetchExactAppliance(variant);
        if (exactVariant) return [exactVariant];

        const rpcVariantMatches = await fetchModelsRpc(variant);
        if (rpcVariantMatches.length) {
          const rpcVariantAppliances = await fetchAppliancesByModels(rpcVariantMatches);
          if (rpcVariantAppliances.length) return uniqueByModel(rpcVariantAppliances);
        }

        const prefixVariantMatches = await fetchPrefixCandidates(variant);
        if (prefixVariantMatches.length) return uniqueByModel(prefixVariantMatches);
      }

      const doubleVariants = buildTypoVariantsTwice(q);

      for (const variant of doubleVariants) {
        const exactVariant = await fetchExactAppliance(variant);
        if (exactVariant) return [exactVariant];

        const rpcVariantMatches = await fetchModelsRpc(variant);
        if (rpcVariantMatches.length) {
          const rpcVariantAppliances = await fetchAppliancesByModels(rpcVariantMatches);
          if (rpcVariantAppliances.length) return uniqueByModel(rpcVariantAppliances);
        }

        const prefixVariantMatches = await fetchPrefixCandidates(variant);
        if (prefixVariantMatches.length) return uniqueByModel(prefixVariantMatches);
      }

      return [];
    }

    if (!base) {
      statusEl.textContent = "Chybí základ modelu ve vyhledávacím poli.";
      listEl.innerHTML = "";
      return;
    }

    try {
      const candidates = uniqueByModel(await fetchPossibleModelCandidates(base));

      if (candidates.length === 1) {
        window.location.replace(applianceUrl(candidates[0]));
        return;
      }

      if (candidates.length > 1) {
  const initiallyVisibleCount = 6;
  const visibleCandidates = candidates.slice(0, initiallyVisibleCount);
  const hiddenCandidates = candidates.slice(initiallyVisibleCount);

  statusEl.innerHTML =
    'Nalezli jsme ' + candidates.length + ' možných modelů pro zadané označení <strong>' +
    escapeHtml(base) +
    '</strong>. Vyberte prosím správnou možnost:';

  const renderCandidateItem = (item) => {
    const model = (item.model_norm || "").trim();
    const href = applianceUrl(item);

    return (
      '<li>' +
        '<a href="' + escapeHtml(href) + '" style="display:block; padding:14px 16px; border:1px solid rgba(42,56,133,0.12); border-left:6px solid #69c7d0; border-radius:12px; text-decoration:none; color:inherit; background:#fff; box-shadow:0 6px 14px rgba(0,0,0,0.04);">' +
          '<strong>' + escapeHtml(model) + '</strong>' +
        '</a>' +
      '</li>'
    );
  };

  listEl.innerHTML =
    '<ul style="list-style:none; padding:0; margin:0; display:grid; gap:12px;">' +
      visibleCandidates.map(renderCandidateItem).join("") +
    '</ul>' +
    (
      hiddenCandidates.length
        ? (
            '<div id="boschino-more-models" hidden style="margin-top:12px;">' +
              '<ul style="list-style:none; padding:0; margin:0; display:grid; gap:12px;">' +
                hiddenCandidates.map(renderCandidateItem).join("") +
              '</ul>' +
            '</div>' +
            '<button type="button" id="boschino-show-more-models" style="margin-top:14px; min-height:46px; padding:0 18px; border:1px solid rgba(42,56,133,0.18); background:#fff; color:#2a3885; font-weight:800; cursor:pointer; border-radius:10px;">' +
              'Zobrazit další' +
            '</button>'
          )
        : ''
    );

  const showMoreBtn = document.getElementById('boschino-show-more-models');
  const moreModelsEl = document.getElementById('boschino-more-models');

  if (showMoreBtn && moreModelsEl) {
    showMoreBtn.addEventListener('click', function () {
      moreModelsEl.hidden = false;
      showMoreBtn.remove();
    });
  }

  return;
}

      statusEl.innerHTML =
        'Pro zadané označení <strong>' + escapeHtml(base) + '</strong> jsme zatím nenašli žádné možné modely.';
      listEl.innerHTML = "";
    } catch (e) {
      console.error("Model picker error:", e);
      statusEl.textContent = "Při načítání možných modelů došlo k chybě.";
      listEl.innerHTML = "";
    }
  })();
});
</script>

<script>
document.addEventListener('DOMContentLoaded', function () {
  const triggers = document.querySelectorAll('.boschino-appliance-trigger');
  const panels = document.querySelectorAll('.boschino-appliance-content');

  function closeAll() {
    triggers.forEach(btn => btn.classList.remove('active'));
    panels.forEach(panel => panel.classList.remove('active'));
  }

  triggers.forEach(trigger => {
    trigger.addEventListener('click', function () {
      const target = this.dataset.target;
      const panel = document.querySelector('.boschino-appliance-content[data-panel="' + target + '"]');
      const isAlreadyOpen = this.classList.contains('active');

      if (isAlreadyOpen) {
        closeAll();
        return;
      }

      closeAll();
      this.classList.add('active');

      if (panel) {
        panel.classList.add('active');
      }
    });
  });
});
</script>

<script>
document.addEventListener('DOMContentLoaded', function () {
  const wrapper = document.querySelector('.boschino-fallback');
  const toggle = document.querySelector('.boschino-fallback-toggle');
  const statusEl = document.getElementById('boschino-fallback-status');
  const gridEl = document.getElementById('boschino-fallback-grid');

  if (!wrapper || !toggle || !statusEl || !gridEl) return;

  const SUPABASE_URL = 'https://hbntpqlpcrodrhfjxhpv.supabase.co';
  const SUPABASE_PUBLISHABLE_KEY = 'sb_publishable_py5U4zoYoBusjy_rngRuWg_IcZ6o-AV';
  const SHOPIFY_STOREFRONT_TOKEN = '7ca8d15c338fa86a89f0c7f4670ba6b2';
  const SHOPIFY_GRAPHQL_URL = window.location.origin + '/api/2024-10/graphql.json';

  let isLoaded = false;

  function escapeHtml(value) {
    return String(value || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatPrice(amount, currencyCode) {
    const numericAmount = Number(amount);
    if (Number.isNaN(numericAmount)) return '';

    try {
      return new Intl.NumberFormat('cs-CZ', {
        style: 'currency',
        currency: currencyCode || 'CZK'
      }).format(numericAmount);
    } catch (error) {
      return `${numericAmount.toFixed(2)} ${currencyCode || 'CZK'}`;
    }
  }

  function getBaseFromUrl() {
    const params = new URLSearchParams(window.location.search);
    return (params.get('base') || '').trim().toUpperCase();
  }

  async function fetchFitmentsByBase(base) {
    const isWildcard = String(base || '').includes('?');
    const pattern = isWildcard
      ? String(base || '').trim().toUpperCase().replace(/\?/g, '_')
      : String(base || '').trim().toUpperCase() + '%';

    const url =
      `${SUPABASE_URL}/rest/v1/fitments_v2` +
      `?select=part_number` +
      `&model_norm=like.${encodeURIComponent(pattern)}` +
      `&limit=1000`;

    const response = await fetch(url, {
      headers: {
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${SUPABASE_PUBLISHABLE_KEY}`
      }
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Fitments chyba: ${response.status} ${errorText}`);
    }

    return response.json();
  }

  async function fetchPartsByPartNumbers(partNumbers) {
    if (!partNumbers.length) return [];

    const url =
      `${SUPABASE_URL}/rest/v1/parts` +
      `?select=part_number,title,shopify_product_gid` +
      `&part_number=in.(${partNumbers.join(',')})` +
      `&limit=1000`;

    const response = await fetch(url, {
      headers: {
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${SUPABASE_PUBLISHABLE_KEY}`
      }
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Parts chyba: ${response.status} ${errorText}`);
    }

    return response.json();
  }

  async function fetchShopifyProductsBatch(productGids) {
    if (!productGids.length) return [];

    const queryParts = productGids.map((gid, index) => {
      const safeGid = JSON.stringify(gid);
      return `
        product_${index}: node(id: ${safeGid}) {
          ... on Product {
            id
            handle
            title
            onlineStoreUrl
            featuredImage {
              url
              altText
            }
            images(first: 1) {
              edges {
                node {
                  url
                  altText
                }
              }
            }
            priceRange {
              minVariantPrice {
                amount
                currencyCode
              }
            }
            metafield(namespace: "custom", key: "termin_dodani") {
              value
            }
            variants(first: 1) {
              edges {
                node {
                  id
                  availableForSale
                  quantityAvailable
                }
              }
            }
          }
        }
      `;
    });

    const graphqlQuery = `
      query FallbackProductsByGid {
        ${queryParts.join('\n')}
      }
    `;

    const response = await fetch(SHOPIFY_GRAPHQL_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Storefront-Access-Token': SHOPIFY_STOREFRONT_TOKEN
      },
      body: JSON.stringify({ query: graphqlQuery })
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Shopify Storefront API chyba: ${response.status} ${errorText}`);
    }

    const payload = await response.json();

    if (payload.errors && payload.errors.length) {
      throw new Error(`Shopify GraphQL chyba: ${payload.errors.map(item => item.message).join(', ')}`);
    }

    const data = payload.data || {};
    return productGids.map((gid, index) => data[`product_${index}`]).filter(Boolean);
  }

  async function fetchShopifyProductsByGids(productGids) {
    const uniqueGids = [...new Set(productGids.filter(Boolean))];
    const batchSize = 20;
    const results = [];

    for (let i = 0; i < uniqueGids.length; i += batchSize) {
      const batch = uniqueGids.slice(i, i + batchSize);
      const batchProducts = await fetchShopifyProductsBatch(batch);
      results.push(...batchProducts);
    }

    return results;
  }

  function getStockState(product) {
    const firstVariant = product?.variants?.edges?.[0]?.node || null;
    const qty = firstVariant ? Number(firstVariant.quantityAvailable || 0) : 0;
    const available = firstVariant ? firstVariant.availableForSale === true : false;
    const terminDodani = product?.metafield?.value || '';
    const terminNorm = String(terminDodani).trim().toLowerCase();

    if (['vyrazeno', 'vyřazeno'].includes(terminNorm)) {
      return {
        sortOrder: 3,
        stockText: 'Trvale vyřazeno',
        stockClass: 'boschino-stock__status--out',
        canBuy: false,
        variantId: firstVariant ? String(firstVariant.id || '').split('/').pop() : ''
      };
    }

    if (qty > 0) {
      return {
        sortOrder: 1,
        stockText: qty === 1 ? 'Poslední kus skladem' : 'Skladem',
        stockClass: 'boschino-stock__status--in',
        canBuy: !!firstVariant,
        variantId: firstVariant ? String(firstVariant.id || '').split('/').pop() : ''
      };
    }

    if (available) {
      return {
        sortOrder: 2,
        stockText: ['neznamo', 'neznámo'].includes(terminNorm) ? 'Upřesnění po objednání' : 'Na objednávku',
        stockClass: 'boschino-stock__status--order',
        canBuy: !!firstVariant,
        variantId: firstVariant ? String(firstVariant.id || '').split('/').pop() : ''
      };
    }

    return {
      sortOrder: 3,
      stockText: 'Trvale vyřazeno',
      stockClass: 'boschino-stock__status--out',
      canBuy: false,
      variantId: firstVariant ? String(firstVariant.id || '').split('/').pop() : ''
    };
  }

  function renderCard(part, product) {
    const productUrl = product.onlineStoreUrl || `/products/${product.handle}`;
    const fallbackImage = product?.images?.edges?.[0]?.node || null;
    const imageUrl = product?.featuredImage?.url || fallbackImage?.url || '';
    const imageAlt = product?.featuredImage?.altText || fallbackImage?.altText || product?.title || '';
    const price = product?.priceRange?.minVariantPrice
      ? formatPrice(product.priceRange.minVariantPrice.amount, product.priceRange.minVariantPrice.currencyCode)
      : '';

    const stock = getStockState(product);

    return `
      <li class="grid__item">
        <div class="card-wrapper product-card-wrapper">
          <div class="card card--standard card--media" tabindex="-1">
            <div class="card__inner">
              <div class="card__media">
                <a href="${escapeHtml(productUrl)}" class="media media--transparent">
                  ${
                    imageUrl
                      ? `<img src="${escapeHtml(imageUrl)}" alt="${escapeHtml(imageAlt)}" loading="lazy">`
                      : `<div class="boschino-image-placeholder"></div>`
                  }
                </a>
              </div>
            </div>

            <div class="card__content">
              <div class="card__information">
                <h3 class="card__heading h5">
                  <a href="${escapeHtml(productUrl)}" class="full-unstyled-link">
                    ${escapeHtml(product.title || part.title || '')}
                  </a>
                </h3>

                <div class="card-information">
                  ${
                    stock.canBuy
                      ? `
                        <div class="price">
                          <div class="price__container">
                            <div class="price__regular">
                              <span class="price-item price-item--regular">${escapeHtml(price)}</span>
                            </div>
                          </div>
                        </div>
                      `
                      : `
                        <div class="price" style="visibility:hidden">
                          <div class="price__container">
                            <div class="price__regular">
                              <span class="price-item price-item--regular">0</span>
                            </div>
                          </div>
                        </div>
                      `
                  }

                  <div class="boschino-stock">
                    <span class="inventory-status-with-tooltip" tabindex="0">
                      <span class="boschino-stock__status ${stock.stockClass}">
                        ${escapeHtml(stock.stockText)}
                      </span>
                      <span class="inventory-tooltip">
                        ${escapeHtml(
                          stock.stockClass === 'boschino-stock__status--in'
                            ? 'Odesíláme ihned s doručením následující pracovní den.'
                            : stock.stockText === 'Upřesnění po objednání'
                              ? 'Termín dodání upřesníme po Vašem objednání.'
                              : stock.stockClass === 'boschino-stock__status--order'
                                ? 'Tyto díly obvykle stíháme dodat do týdne od Vaší objednávky..'
                                : 'Tento díl je bohužel vyřazen a nelze jej vložit do objednávky.'
                        )}
                      </span>
                    </span>
                  </div>
                </div>
              </div>

              <div class="boschino-actions">
                <form method="post" action="/cart/add" class="boschino-card-buy" data-boschino-card-buy>
                  <input type="hidden" name="id" value="${escapeHtml(stock.variantId)}">

                  <div class="boschino-quantity" data-boschino-qty>
                    <button type="button" class="boschino-minus" data-qty-minus ${stock.canBuy ? '' : 'disabled'} aria-label="Odebrat 1 ks"></button>

                    <input
                      type="number"
                      name="quantity"
                      value="${stock.canBuy ? '1' : '0'}"
                      min="${stock.canBuy ? '1' : '0'}"
                      step="1"
                      inputmode="numeric"
                      pattern="[0-9]*"
                      aria-label="Počet kusů"
                      data-qty-input
                      ${stock.canBuy ? '' : 'disabled'}
                    >

                    <button type="button" class="boschino-plus" data-qty-plus ${stock.canBuy ? '' : 'disabled'} aria-label="Přidat 1 ks"></button>
                  </div>

                  <div class="boschino-cta">
                    <a class="boschino-cta__detail" href="${escapeHtml(productUrl)}">Detail produktu</a>

                    <div class="boschino-cta__cart">
                      <button type="submit" class="boschino-cta__btn" ${stock.canBuy ? '' : 'disabled'} aria-label="Přidat do košíku">
                        <svg class="boschino-cart-ico" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                          <path d="M7 18c-1.1 0-1.99.9-1.99 2S5.9 22 7 22s2-.9 2-2-.9-2-2-2zm10 0c-1.1 0-1.99.9-1.99 2S15.9 22 17 22s2-.9 2-2-.9-2-2-2zM7.2 6h13.4c.8 0 1.4.7 1.2 1.5l-1.6 7.2c-.2.7-.8 1.3-1.6 1.3H8.1c-.7 0-1.4-.5-1.6-1.2L4.3 3H2V1h3.7c.6 0 1.1.4 1.2 1l.3 2z"></path>
                        </svg>
                      </button>
                    </div>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </li>
    `;
  }

  function bindQuantityControls(scope) {
    scope.querySelectorAll('[data-boschino-qty]').forEach((qtyWrap) => {
      const input = qtyWrap.querySelector('[data-qty-input]');
      const minus = qtyWrap.querySelector('[data-qty-minus]');
      const plus = qtyWrap.querySelector('[data-qty-plus]');
      if (!input || !minus || !plus) return;

      const isDisabled = input.disabled || minus.disabled || plus.disabled;

      if (isDisabled) {
        input.value = '0';
        minus.onclick = null;
        plus.onclick = null;
        input.oninput = null;
        return;
      }

      minus.onclick = function (event) {
        event.preventDefault();
        event.stopPropagation();
        const current = parseInt(input.value || '1', 10);
        input.value = String(Math.max(1, current - 1));
      };

      plus.onclick = function (event) {
        event.preventDefault();
        event.stopPropagation();
        const current = parseInt(input.value || '1', 10);
        input.value = String(current + 1);
      };

      input.oninput = function () {
        let value = parseInt(input.value || '1', 10);
        if (Number.isNaN(value) || value < 1) value = 1;
        input.value = String(value);
      };
    });
  }

  function renderProducts(parts, shopifyProducts) {
    const productByGid = new Map(shopifyProducts.map((product) => [product.id, product]));

    const enriched = parts
      .map((part) => {
        const product = productByGid.get(part.shopify_product_gid);
        if (!product) return null;
        return {
          part,
          product,
          stock: getStockState(product)
        };
      })
      .filter(Boolean)
      .sort((a, b) => {
        if (a.stock.sortOrder !== b.stock.sortOrder) {
          return a.stock.sortOrder - b.stock.sortOrder;
        }

        const aHasImage = (a.product.featuredImage?.url || a.product.images?.edges?.[0]?.node?.url) ? 1 : 0;
        const bHasImage = (b.product.featuredImage?.url || b.product.images?.edges?.[0]?.node?.url) ? 1 : 0;

        if (aHasImage !== bHasImage) {
          return bHasImage - aHasImage;
        }

        const nameA = (a.product.title || '').toLowerCase();
        const nameB = (b.product.title || '').toLowerCase();

        return nameA.localeCompare(nameB, 'cs');
      });

    if (!enriched.length) {
      statusEl.textContent = 'Produkty byly nalezeny v databázi, ale nepodařilo se je načíst ze Shopify.';
      return;
    }

    gridEl.innerHTML = enriched.map(({ part, product }) => renderCard(part, product)).join('');
    gridEl.hidden = false;
    statusEl.textContent = `Nalezeno ${enriched.length} kompatibilních produktů.`;
    bindQuantityControls(gridEl);
  }

  async function loadFallbackProducts() {
    const base = getBaseFromUrl();

    if (!base) {
      statusEl.textContent = 'Chybí základ modelu ve vyhledávacím poli.';
      return;
    }

    statusEl.textContent = 'Načítám kompatibilní díly…';

    const fitments = await fetchFitmentsByBase(base);

    if (!Array.isArray(fitments) || !fitments.length) {
      statusEl.textContent = 'Nenašli jsme žádné kompatibilní díly.';
      return;
    }

    const partNumbers = [...new Set(
      fitments
        .map((item) => (item.part_number || '').trim())
        .filter(Boolean)
    )];

    if (!partNumbers.length) {
      statusEl.textContent = 'Nenašli jsme žádná čísla dílů.';
      return;
    }

    const parts = await fetchPartsByPartNumbers(partNumbers);

    if (!Array.isArray(parts) || !parts.length) {
      statusEl.textContent = 'Díly jsme nenašli.';
      return;
    }

    const uniqueParts = [];
    const seenGids = new Set();

    parts.forEach((part) => {
      const gid = (part.shopify_product_gid || '').trim();
      if (!gid || seenGids.has(gid)) return;
      seenGids.add(gid);
      uniqueParts.push(part);
    });

    if (!uniqueParts.length) {
      statusEl.textContent = 'Díly nemají navázané Shopify produkty.';
      return;
    }

    const shopifyProducts = await fetchShopifyProductsByGids(
      uniqueParts.map((item) => item.shopify_product_gid)
    );

    renderProducts(uniqueParts, shopifyProducts);
    isLoaded = true;
  }

  toggle.addEventListener('click', async function () {
    const isOpen = wrapper.classList.contains('active');

    if (isOpen) {
      wrapper.classList.remove('active');
      toggle.setAttribute('aria-expanded', 'false');
      return;
    }

    wrapper.classList.add('active');
    toggle.setAttribute('aria-expanded', 'true');

    if (isLoaded) return;

    try {
      await loadFallbackProducts();
    } catch (error) {
      console.error(error);
      statusEl.textContent = `Chyba: ${error.message}`;
    }
  });
});
</script>
